import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Migrations","description":"","frontmatter":{},"headers":[],"relativePath":"database/migrations.md","filePath":"database/migrations.md","lastUpdated":1786321880000}`),a={name:`database/migrations.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /database/migrations.md for this page in Markdown format</div><h1 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to “Migrations”">​</a></h1><p>Drizzle Kit generates SQL migrations by diffing your TypeScript schema against the latest snapshot. Migration files live in <code>db/migrations/</code> alongside a journal that tracks applied versions.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to “Workflow”">​</a></h2><p><strong>1. Edit the schema</strong> in <code>db/schema/</code>.</p><p><strong>2. Generate a migration:</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:generate</span></span></code></pre></div><p>This produces a numbered SQL file (e.g., <code>0001_add_product_table.sql</code>) in <code>db/migrations/</code>.</p><p><strong>3. Review the generated SQL.</strong> Drizzle Kit&#39;s output is generally correct, but always check for destructive operations – column drops, type changes, or data loss.</p><p><strong>4. Apply the migration:</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate</span></span></code></pre></div><p><strong>5. Verify in Drizzle Studio:</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:studio</span></span></code></pre></div><h2 id="push-vs-migrate" tabindex="-1">Push vs Migrate <a class="header-anchor" href="#push-vs-migrate" aria-label="Permalink to “Push vs Migrate”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>Use when</th></tr></thead><tbody><tr><td><code>bun db:migrate</code></td><td>Applies pending migrations to local DB</td><td>Local and shared development</td></tr><tr><td><code>bun db:migrate:&lt;env&gt;</code></td><td>Applies pending migrations to named DB</td><td>Staging and production</td></tr><tr><td><code>bun db:push</code></td><td>Syncs schema directly, no migration files</td><td>Local development, rapid prototyping</td></tr></tbody></table><p><code>push</code> is faster during development since it skips migration file generation. Switch to <code>migrate</code> when you need reproducible, reviewable changes.</p><h2 id="targeting-environments" tabindex="-1">Targeting Environments <a class="header-anchor" href="#targeting-environments" aria-label="Permalink to “Targeting Environments”">​</a></h2><p>Append <code>:staging</code> or <code>:production</code> to run against other databases:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate:staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate:production</span></span></code></pre></div><p>These set <code>ENVIRONMENT</code> internally and load only the matching <code>.env.{env}.local</code> file. They fail when that file is missing instead of falling back to a local URL, and its <code>DATABASE_URL</code> overrides an inherited shell value.</p><h2 id="migration-history-checks" tabindex="-1">Migration History Checks <a class="header-anchor" href="#migration-history-checks" aria-label="Permalink to “Migration History Checks”">​</a></h2><p>After merging branches that both generated migrations, run:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:check</span></span></code></pre></div><p>This checks the generated migration history for conflicting branches. It does not connect to or detect drift in a live database; use introspection and a deliberate reconciliation migration for out-of-band database changes.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li><strong>Name your migrations</strong> – <code>bun db:generate --name add-product-table</code> produces clearer filenames than auto-numbered defaults.</li><li><strong>One concern per migration</strong> – avoid bundling unrelated schema changes. Smaller migrations are easier to review and roll back.</li><li><strong>Never edit applied migrations</strong> – if a migration has already run in staging or production, create a new migration to correct issues.</li><li><strong>Review before applying</strong> – <code>db:generate</code> writes SQL to disk. Read the file before running <code>db:migrate</code>.</li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};